size_t i;
int valid = 1;
int just_entered_recovery = 0;
double abs_cur, abs_pred;
adcs_vec3_t desired_torque = {0.0, 0.0, 0.0};
double vals[3];
double prev_vals[3];

/* Input validation */
if ((wo_input.wheels == NULL) || (wo_input.count != 4U)) {
    valid = 0;
}
if (valid && (wo_input.enable != 0) && (wo_input.enable != 1)) {
    valid = 0;
}
if (valid) {
    if ((!isfinite(wo_config.release_rad_s)) || (!isfinite(wo_config.warn_rad_s)) ||
        (!isfinite(wo_config.trip_rad_s)) || (wo_config.release_rad_s < 0.0) ||
        !(wo_config.release_rad_s < wo_config.warn_rad_s) ||
        !(wo_config.warn_rad_s < wo_config.trip_rad_s)) {
        valid = 0;
    }
}
if (valid) {
    if ((!isfinite(wo_config.dt_s)) || (wo_config.dt_s <= 0.0) ||
        (!isfinite(wo_config.prediction_horizon_s)) || (wo_config.prediction_horizon_s <= 0.0) ||
        (!isfinite(wo_config.torque_limit)) || (wo_config.torque_limit <= 0.0) ||
        (!isfinite(wo_config.torque_slew)) || (wo_config.torque_slew <= 0.0) ||
        (!isfinite(wo_config.gain)) || (wo_config.gain < 0.0)) {
        valid = 0;
    }
}
if (valid) {
    if ((wo_config.minimum_active_cycles < 1U) || (wo_config.minimum_active_cycles > 100U) ||
        (wo_config.release_cycles < 1U) || (wo_config.release_cycles > 100U) ||
        (wo_config.recovery_cycles < 1U) || (wo_config.recovery_cycles > 100U)) {
        valid = 0;
    }
}
if (valid) {
    for (i = 0; i < 4U; i++) {
        if ((!isfinite(wo_input.wheels[i].inertia_kg_m2)) ||
            (!isfinite(wo_input.wheels[i].speed_rad_s)) ||
            (wo_input.wheels[i].inertia_kg_m2 < 0.0) ||
            (!isfinite(wo_input.wheels[i].axis_body.x)) ||
            (!isfinite(wo_input.wheels[i].axis_body.y)) ||
            (!isfinite(wo_input.wheels[i].axis_body.z))) {
            valid = 0;
            break;
        }
    }
}

/* Disable: reset history and output state */
if (valid && (wo_input.enable == 0)) {
    wo_state.mode = WO_OFF;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.recovery_count = 0U;
    wo_state.history_initialized = 0;
    wo_state.previous_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.mode = WO_OFF;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

/* Invalid input or config -> FAULT, zero commands */
if (!valid) {
    wo_state.mode = WO_FAULT;
    wo_state.history_initialized = 0;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}

/* Sum wheel momentum */
if (adcs_wheel_momentum(wo_input.wheels, wo_input.count, &wo_output.momentum) != ADCS_OK) {
    wo_state.mode = WO_FAULT;
    wo_state.history_initialized = 0;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}
if ((!isfinite(wo_output.momentum.x)) || (!isfinite(wo_output.momentum.y)) ||
    (!isfinite(wo_output.momentum.z))) {
    wo_state.mode = WO_FAULT;
    wo_state.history_initialized = 0;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.recovery_count = 0U;
    wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.momentum_norm = 0.0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.predicted_trip_mask = 0U;
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    return;
}
wo_output.momentum_norm = adcs_vec3_norm(&wo_output.momentum);

/* Initialize or update speed history */
if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
    wo_state.history_initialized = 1;
} else {
    for (i = 0; i < 4U; i++) {
        wo_output.acceleration_rad_s2[i] =
            (wo_input.wheels[i].speed_rad_s - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
        wo_output.predicted_speed_rad_s[i] =
            wo_input.wheels[i].speed_rad_s +
            wo_output.acceleration_rad_s2[i] * wo_config.prediction_horizon_s;
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
}
for (i = 0; i < 4U; i++) {
    if ((!isfinite(wo_output.acceleration_rad_s2[i])) ||
        (!isfinite(wo_output.predicted_speed_rad_s[i]))) {
        wo_state.mode = WO_FAULT;
        wo_state.history_initialized = 0;
        wo_output.mode = WO_FAULT;
        wo_output.clean = 0U;
        wo_output.elapsed = 0U;
        wo_output.recovery_count = 0U;
        wo_output.momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
        wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
        wo_output.momentum_norm = 0.0;
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        for (i = 0; i < 4U; i++) {
            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        wo_output.predicted_trip_mask = 0U;
        wo_output.saturation_mask = 0U;
        wo_output.slew_mask = 0U;
        return;
    }
}

/* Compute maxima and per-wheel predicted trip mask */
wo_output.maximum_speed = 0.0;
wo_output.predicted_maximum_speed = 0.0;
wo_output.predicted_trip_mask = 0U;
for (i = 0; i < 4U; i++) {
    abs_cur = fabs(wo_input.wheels[i].speed_rad_s);
    abs_pred = fabs(wo_output.predicted_speed_rad_s[i]);
    if (abs_cur > wo_output.maximum_speed) {
        wo_output.maximum_speed = abs_cur;
    }
    if (abs_pred > wo_output.predicted_maximum_speed) {
        wo_output.predicted_maximum_speed = abs_pred;
    }
    if (abs_pred >= wo_config.trip_rad_s) {
        wo_output.predicted_trip_mask |= (unint32)(1U << i);
    }
}

/* Default output torque/slew/mask cleared for this cycle */
wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
wo_output.saturation_mask = 0U;
wo_output.slew_mask = 0U;

switch (wo_state.mode) {
case WO_OFF:
    if (wo_output.predicted_maximum_speed >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
        wo_state.recovery_count = 0U;
        /* fall-through handled below by ACTIVE case */
    } else if (wo_output.predicted_maximum_speed >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    }
    break;
case WO_WATCH:
    if (wo_output.predicted_maximum_speed >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
        wo_state.recovery_count = 0U;
    } else if (wo_output.predicted_maximum_speed < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
    }
    break;
case WO_ACTIVE:
    wo_state.elapsed++;
    desired_torque = adcs_vec3_scale(&wo_output.momentum, -wo_config.gain);
    vals[0] = desired_torque.x;
    vals[1] = desired_torque.y;
    vals[2] = desired_torque.z;
    for (i = 0; i < 3U; i++) {
        if (vals[i] > wo_config.torque_limit) {
            vals[i] = wo_config.torque_limit;
            wo_output.saturation_mask |= (unint32)(1U << i);
        } else if (vals[i] < -wo_config.torque_limit) {
            vals[i] = -wo_config.torque_limit;
            wo_output.saturation_mask |= (unint32)(1U << i);
        }
    }
    prev_vals[0] = wo_state.previous_torque.x;
    prev_vals[1] = wo_state.previous_torque.y;
    prev_vals[2] = wo_state.previous_torque.z;
    for (i = 0; i < 3U; i++) {
        double delta = vals[i] - prev_vals[i];
        if (delta > wo_config.torque_slew) {
            vals[i] = prev_vals[i] + wo_config.torque_slew;
            wo_output.slew_mask |= (unint32)(1U << i);
        } else if (delta < -wo_config.torque_slew) {
            vals[i] = prev_vals[i] - wo_config.torque_slew;
            wo_output.slew_mask |= (unint32)(1U << i);
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    if ((wo_state.elapsed >= wo_config.minimum_active_cycles) &&
        (wo_output.maximum_speed <= wo_config.release_rad_s) &&
        (wo_output.predicted_maximum_speed <= wo_config.release_rad_s)) {
        wo_state.clean++;
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_RECOVERY;
            wo_state.clean = 0U;
            wo_state.recovery_count = 0U;
            just_entered_recovery = 1;
        }
    } else {
        wo_state.clean = 0U;
    }
    break;
case WO_RECOVERY:
    if (wo_output.predicted_maximum_speed >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0U;
        wo_state.clean = 0U;
        wo_state.recovery_count = 0U;
        break;
    }
    /* Non-trip recovery call: increment count, check threshold */
    wo_state.recovery_count++;
    if (wo_state.recovery_count >= wo_config.recovery_cycles) {
        wo_state.mode = WO_OFF;
        wo_state.clean = 0U;
        wo_state.recovery_count = 0U;
        wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
        break;
    }
    /* Command zero through slew limiter */
    prev_vals[0] = wo_state.previous_torque.x;
    prev_vals[1] = wo_state.previous_torque.y;
    prev_vals[2] = wo_state.previous_torque.z;
    vals[0] = 0.0;
    vals[1] = 0.0;
    vals[2] = 0.0;
    for (i = 0; i < 3U; i++) {
        double delta = vals[i] - prev_vals[i];
        if (delta > wo_config.torque_slew) {
            vals[i] = prev_vals[i] + wo_config.torque_slew;
            wo_output.slew_mask |= (unint32)(1U << i);
        } else if (delta < -wo_config.torque_slew) {
            vals[i] = prev_vals[i] - wo_config.torque_slew;
            wo_output.slew_mask |= (unint32)(1U << i);
        }
    }
    wo_output.torque = (adcs_vec3_t){vals[0], vals[1], vals[2]};
    wo_state.previous_torque = wo_output.torque;
    break;
case WO_FAULT:
default:
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    wo_output.saturation_mask = 0U;
    wo_output.slew_mask = 0U;
    break;
}

wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;
(void)just_entered_recovery;

