wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;
wo_output.torque = (adcs_vec3_t){ vals[0], vals[1], vals[2] };
wo_state.previous_torque = wo_output.torque;
wo_output.saturation_mask = sat_mask;
wo_output.slew_mask = sl_mask;

candidates.misra:
size_t i;
int cfg_ok;
double acc, cur, pred, absmax_cur, absmax_pred;
adcs_vec3_t h = {0,0,0};
double vals[3];
uint32_t sat_mask = 0U, sl_mask = 0U;

cfg_ok = (int)((wo_input.enable == 0 || wo_input.enable == 1) &&
               (wo_input.wheels != NULL) && (wo_input.count == 4U));
if (cfg_ok) {
    if (!(wo_config.release_rad_s >= 0.0 &&
          wo_config.release_rad_s < wo_config.warn_rad_s &&
          wo_config.warn_rad_s < wo_config.trip_rad_s))
        cfg_ok = 0;
    if (!(isfinite(wo_config.dt_s) && wo_config.dt_s > 0.0)) cfg_ok = 0;
    if (!(isfinite(wo_config.prediction_horizon_s) && wo_config.prediction_horizon_s > 0.0)) cfg_ok = 0;
    if (!(isfinite(wo_config.torque_limit) && wo_config.torque_limit > 0.0)) cfg_ok = 0;
    if (!(isfinite(wo_config.torque_slew) && wo_config.torque_slew > 0.0)) cfg_ok = 0;
    if (!(isfinite(wo_config.gain) && wo_config.gain >= 0.0)) cfg_ok = 0;
    if (wo_config.minimum_active_cycles < 1U || wo_config.minimum_active_cycles > 100U) cfg_ok = 0;
    if (wo_config.release_cycles < 1U || wo_config.release_cycles > 100U) cfg_ok = 0;
    if (wo_config.recovery_cycles < 1U || wo_config.recovery_cycles > 100U) cfg_ok = 0;
    if (cfg_ok) {
        if (adcs_wheel_momentum(wo_input.wheels, wo_input.count, &h) != ADCS_OK)
            cfg_ok = 0;
        else if (!adcs_is_finite_vec3(&h))
            cfg_ok = 0;
        else {
            /* momentum computed and finite: configuration remains valid */
        }
    }
}

if (wo_input.enable == 0) {
    wo_state.history_initialized = 0;
    wo_state.mode = WO_OFF;
    wo_state.clean = 0; wo_state.elapsed = 0; wo_state.recovery_count = 0;
    wo_state.previous_torque = (adcs_vec3_t){0,0,0};
    wo_output.mode = WO_OFF;
    wo_output.clean = 0; wo_output.elapsed = 0; wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0; wo_output.predicted_maximum_speed = 0.0;
    for (i = 0; i < 4U; i++) { wo_output.acceleration_rad_s2[i]=0.0; wo_output.predicted_speed_rad_s[i]=0.0; }
    wo_output.momentum = (adcs_vec3_t){0,0,0};
    wo_output.torque = (adcs_vec3_t){0,0,0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0U; wo_output.saturation_mask = 0U; wo_output.slew_mask = 0U;
    return;
}

if (!cfg_ok) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.torque = (adcs_vec3_t){0,0,0};
    wo_output.saturation_mask = 0U; wo_output.slew_mask = 0U;
    wo_output.predicted_trip_mask = 0U;
    return;
}

if (!wo_state.history_initialized) {
    for (i = 0; i < 4U; i++)
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    wo_state.history_initialized = 1;
}

absmax_cur = 0.0; absmax_pred = 0.0;
wo_output.predicted_trip_mask = 0U;
for (i = 0; i < 4U; i++) {
    cur = wo_input.wheels[i].speed_rad_s;
    acc = (cur - wo_state.previous_speed_rad_s[i]) / wo_config.dt_s;
    pred = cur + acc * wo_config.prediction_horizon_s;
    wo_state.previous_speed_rad_s[i] = cur;
    wo_output.acceleration_rad_s2[i] = acc;
    wo_output.predicted_speed_rad_s[i] = pred;
    if (fabs(cur)  > absmax_cur)  absmax_cur  = fabs(cur);
    if (fabs(pred) > absmax_pred) absmax_pred = fabs(pred);
    if (fabs(pred) >= wo_config.trip_rad_s)
        wo_output.predicted_trip_mask |= (uint32_t)(1U << i);
}
wo_output.maximum_speed = absmax_cur;
wo_output.predicted_maximum_speed = absmax_pred;
wo_output.momentum = h;
wo_output.momentum_norm = adcs_vec3_norm(&h);

vals[0] = 0.0; vals[1] = 0.0; vals[2] = 0.0;

if (wo_state.mode == WO_OFF) {
    if (absmax_pred >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0; wo_state.clean = 0; wo_state.recovery_count = 0;
    } else if (absmax_pred >= wo_config.warn_rad_s) {
        wo_state.mode = WO_WATCH;
    } else {
        /* remains OFF */
    }
} else if (wo_state.mode == WO_WATCH) {
    if (absmax_pred >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0; wo_state.clean = 0; wo_state.recovery_count = 0;
    } else if (absmax_pred < wo_config.warn_rad_s) {
        wo_state.mode = WO_OFF;
    } else {
        /* remains WATCH */
    }
} else if (wo_state.mode == WO_ACTIVE) {
    double prev[3]; double maxdelta;
    wo_state.elapsed++;
    vals[0] = -wo_config.gain * h.x;
    vals[1] = -wo_config.gain * h.y;
    vals[2] = -wo_config.gain * h.z;
    for (i = 0; i < 3U; i++) {
        if (vals[i] > wo_config.torque_limit) { vals[i] = wo_config.torque_limit; sat_mask |= (uint32_t)(1U << i); }
        else if (vals[i] < -wo_config.torque_limit) { vals[i] = -wo_config.torque_limit; sat_mask |= (uint32_t)(1U << i); }
        else { /* within magnitude limit */ }
    }
    prev[0]=wo_state.previous_torque.x; prev[1]=wo_state.previous_torque.y; prev[2]=wo_state.previous_torque.z;
    maxdelta = wo_config.torque_slew * wo_config.dt_s;
    for (i = 0; i < 3U; i++) {
        double d = vals[i] - prev[i];
        if (d > maxdelta) { vals[i] = prev[i] + maxdelta; sl_mask |= (uint32_t)(1U << i); }
        else if (d < -maxdelta) { vals[i] = prev[i] - maxdelta; sl_mask |= (uint32_t)(1U << i); }
        else { /* within slew limit */ }
    }
    if (absmax_cur <= wo_config.release_rad_s && absmax_pred <= wo_config.release_rad_s)
        wo_state.clean++;
    else
        wo_state.clean = 0;
    if (wo_state.elapsed >= wo_config.minimum_active_cycles &&
        wo_state.clean >= wo_config.release_cycles) {
        wo_state.mode = WO_RECOVERY;
        wo_state.clean = 0; wo_state.recovery_count = 0;
    }
} else if (wo_state.mode == WO_RECOVERY) {
    if (wo_output.predicted_trip_mask != 0U || absmax_pred >= wo_config.trip_rad_s) {
        wo_state.mode = WO_ACTIVE;
        wo_state.elapsed = 0; wo_state.clean = 0; wo_state.recovery_count = 0;
    } else {
        double prev[3]; double maxdelta;
        vals[0] = 0.0; vals[1] = 0.0; vals[2] = 0.0;
        prev[0]=wo_state.previous_torque.x; prev[1]=wo_state.previous_torque.y; prev[2]=wo_state.previous_torque.z;
        maxdelta = wo_config.torque_slew * wo_config.dt_s;
        for (i = 0; i < 3U; i++) {
            double d = vals[i] - prev[i];
            if (d > maxdelta) { vals[i] = prev[i] + maxdelta; sl_mask |= (uint32_t)(1U << i); }
            else if (d < -maxdelta) { vals[i] = prev[i] - maxdelta; sl_mask |= (uint32_t)(1U << i); }
            else { /* within slew limit */ }
        }
        wo_state.recovery_count++;
        if (wo_state.recovery_count >= wo_config.recovery_cycles) {
            wo_state.mode = WO_OFF;
            wo_state.clean = 0; wo_state.elapsed = 0; wo_state.recovery_count = 0;
        }
    }
} else {
    wo_state.mode = WO_FAULT;
    wo_state.clean = 0; wo_state.elapsed = 0; wo_state.recovery_count = 0;
    vals[0] = 0.0; vals[1] = 0.0; vals[2] = 0.0;
}

wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;
wo_output.recovery_count = wo_state.recovery_count;
wo_output.torque = (adcs_vec3_t){ vals[0], vals[1], vals[2] };
wo_state.previous_torque = wo_output.torque;
wo_output.saturation_mask = sat_mask;
wo_output.slew_mask = sl_mask;
